// A class template declared but not defined.
// Its purpose is to trigger a compiler error.
template<typename T> 
class TD; // TD stands for Type Displayer

const int theAnswer = 42;
auto x = theAnswer;
auto y = &theAnswer;

// To see the types of x and y, declare variables
// of the TD template with those types.
// The compiler error will reveal the deduced types.
TD<decltype(x)> xType;
TD<decltype(y)> yType;
